import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l2_p30_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor fused_groupnorm_hardtanh(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int num_groups,
    double eps,
    double min_val,
    double max_val
);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("fused_groupnorm_hardtanh", &fused_groupnorm_hardtanh,
          "Fused GroupNorm + HardTanh (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Fused GroupNorm + HardTanh kernel.
// Grid: (batch_size * num_groups,)  Block: min(group_size, 1024) threads
// Each block handles exactly one (batch, group) pair.
__global__ void fused_groupnorm_hardtanh_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    int batch_size,
    int num_groups,
    int group_size,
    float eps,
    float min_val,
    float max_val
) {
    // blockIdx.x encodes (batch_idx * num_groups + group_idx)
    int batch_idx = blockIdx.x / num_groups;
    int group_idx = blockIdx.x % num_groups;

    int base = batch_idx * num_groups * group_size + group_idx * group_size;

    // Phase 1: compute mean and variance using Welford online reduction
    // Each thread accumulates its portion via stride loop
    float local_sum = 0.0f;
    float local_sq  = 0.0f;

    for (int i = threadIdx.x; i < group_size; i += blockDim.x) {
        float v = input[base + i];
        local_sum += v;
        local_sq  += v * v;
    }

    // Warp-level reduction
    unsigned mask = 0xffffffff;
    for (int offset = 16; offset > 0; offset >>= 1) {
        local_sum += __shfl_down_sync(mask, local_sum, offset);
        local_sq  += __shfl_down_sync(mask, local_sq,  offset);
    }

    // Store per-warp results to shared memory
    extern __shared__ float smem[]; // 2 * num_warps floats
    int warp_id   = threadIdx.x >> 5;
    int lane_id   = threadIdx.x & 31;
    int num_warps = (blockDim.x + 31) >> 5;

    float* smem_sum = smem;
    float* smem_sq  = smem + num_warps;

    if (lane_id == 0) {
        smem_sum[warp_id] = local_sum;
        smem_sq [warp_id] = local_sq;
    }
    __syncthreads();

    // Final reduction in first warp
    float block_sum = 0.0f;
    float block_sq  = 0.0f;
    if (threadIdx.x < num_warps) {
        block_sum = smem_sum[threadIdx.x];
        block_sq  = smem_sq [threadIdx.x];
    }
    if (warp_id == 0) {
        for (int offset = 16; offset > 0; offset >>= 1) {
            block_sum += __shfl_down_sync(mask, block_sum, offset);
            block_sq  += __shfl_down_sync(mask, block_sq,  offset);
        }
    }

    __shared__ float s_mean, s_inv_std;
    if (threadIdx.x == 0) {
        float mean   = block_sum / group_size;
        float var    = block_sq  / group_size - mean * mean;
        s_mean       = mean;
        s_inv_std    = rsqrtf(var + eps);
    }
    __syncthreads();

    float mean    = s_mean;
    float inv_std = s_inv_std;

    // Phase 2: normalize, apply affine, clamp
    int channel_base = group_idx * group_size;
    for (int i = threadIdx.x; i < group_size; i += blockDim.x) {
        float v   = input[base + i];
        float norm = (v - mean) * inv_std;
        float w   = weight[channel_base + i];
        float b   = bias  [channel_base + i];
        float out = norm * w + b;
        // HardTanh clamp
        out = fminf(fmaxf(out, min_val), max_val);
        output[base + i] = out;
    }
}

torch::Tensor fused_groupnorm_hardtanh(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int num_groups,
    double eps,
    double min_val,
    double max_val
) {
    TORCH_CHECK(input.is_cuda(),  "input must be a CUDA tensor");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");

    int batch_size  = input.size(0);
    int out_features = input.size(1);
    int group_size  = out_features / num_groups;

    auto output = torch::empty_like(input);

    // Block size: clamp group_size to a warp multiple <= 1024
    int block_size = group_size;
    if (block_size > 1024) block_size = 1024;
    // Round up to next multiple of 32 for warp efficiency
    block_size = ((block_size + 31) / 32) * 32;
    if (block_size > 1024) block_size = 1024;

    int num_warps = (block_size + 31) / 32;
    size_t smem_bytes = 2 * num_warps * sizeof(float);

    int grid_size = batch_size * num_groups;

    fused_groupnorm_hardtanh_kernel<<<grid_size, block_size, smem_bytes>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        batch_size,
        num_groups,
        group_size,
        static_cast<float>(eps),
        static_cast<float>(min_val),
        static_cast<float>(max_val)
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs a GEMM, applies Group Normalization, and then HardTanh.
        """
    def __init__(self, in_features, out_features, num_groups, hardtanh_min, hardtanh_max):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.gemm = nn.Linear(in_features, out_features)
        self.group_norm = nn.GroupNorm(num_groups, out_features)
        self.hardtanh = nn.Hardtanh(min_val=hardtanh_min, max_val=hardtanh_max)
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Args:
                    x (torch.Tensor): Input tensor of shape (batch_size, in_features).
                Returns:
                    torch.Tensor: Output tensor of shape (batch_size, out_features).
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        x = self.gemm(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        x = _stark_get_extension().fused_groupnorm_hardtanh(
            x.contiguous(),
            self.group_norm.weight,
            self.group_norm.bias,
            self.group_norm.num_groups,
            self.group_norm.eps,
            self.hardtanh.min_val,
            self.hardtanh.max_val,
        )
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        # HardTanh is fused into the CUDA kernel above; nothing to do here.
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        return x
        # <<<END_IMPROVE>>>

