CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// ---------------------------------------------------------------------------
// Vectorized fast-path kernel: group_size == 512, 128 threads, each thread
// handles 4 contiguous elements via float4 loads/stores.
// ---------------------------------------------------------------------------
__global__ __launch_bounds__(128, 4)
void fused_groupnorm_hardtanh_vec4_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    int num_groups,
    float inv_group_size,  // 1.0f / group_size
    float eps,
    float min_val,
    float max_val
) {
    // Each block handles one (batch, group) pair.
    // blockDim.x == 128, group_size == 512 => each thread covers 4 elements.
    const int group_size = 512;
    int batch_idx = blockIdx.x / num_groups;
    int group_idx = blockIdx.x % num_groups;

    int base        = batch_idx * num_groups * group_size + group_idx * group_size;
    int chan_base   = group_idx * group_size;

    // Each thread: vec_idx in [0,128), element range [vec_idx*4, vec_idx*4+4)
    int vec_idx = threadIdx.x;  // 0..127
    int elem    = vec_idx * 4;

    // --- Load float4 from input ---
    float4 in_val = *reinterpret_cast<const float4*>(input + base + elem);
    float v0 = in_val.x, v1 = in_val.y, v2 = in_val.z, v3 = in_val.w;

    // --- Phase 1: local sum and sumsq ---
    float local_sum = v0 + v1 + v2 + v3;
    float local_sq  = v0*v0 + v1*v1 + v2*v2 + v3*v3;

    // Warp-level reduction
    unsigned mask = 0xffffffff;
    for (int offset = 16; offset > 0; offset >>= 1) {
        local_sum += __shfl_down_sync(mask, local_sum, offset);
        local_sq  += __shfl_down_sync(mask, local_sq,  offset);
    }

    // 128 threads => 4 warps; store warp sums to shared memory
    extern __shared__ float smem[];  // 8 floats: 4 sum + 4 sq
    int warp_id = threadIdx.x >> 5;
    int lane_id = threadIdx.x & 31;

    float* smem_sum = smem;
    float* smem_sq  = smem + 4;

    if (lane_id == 0) {
        smem_sum[warp_id] = local_sum;
        smem_sq [warp_id] = local_sq;
    }
    __syncthreads();

    // First warp reduces the 4 warp sums
    float block_sum = 0.0f, block_sq = 0.0f;
    if (threadIdx.x < 4) {
        block_sum = smem_sum[threadIdx.x];
        block_sq  = smem_sq [threadIdx.x];
    }
    if (warp_id == 0) {
        for (int offset = 2; offset > 0; offset >>= 1) {
            block_sum += __shfl_down_sync(mask, block_sum, offset);
            block_sq  += __shfl_down_sync(mask, block_sq,  offset);
        }
    }

    __shared__ float s_mean, s_inv_std;
    if (threadIdx.x == 0) {
        float mean    = block_sum * inv_group_size;
        float var     = block_sq  * inv_group_size - mean * mean;
        s_mean        = mean;
        s_inv_std     = rsqrtf(var + eps);
    }
    __syncthreads();

    float mean    = s_mean;
    float inv_std = s_inv_std;

    // --- Phase 2: load weight/bias, normalize, clamp, store ---
    float4 w_val = *reinterpret_cast<const float4*>(weight + chan_base + elem);
    float4 b_val = *reinterpret_cast<const float4*>(bias   + chan_base + elem);

    float4 out_val;
    out_val.x = fminf(fmaxf((v0 - mean) * inv_std * w_val.x + b_val.x, min_val), max_val);
    out_val.y = fminf(fmaxf((v1 - mean) * inv_std * w_val.y + b_val.y, min_val), max_val);
    out_val.z = fminf(fmaxf((v2 - mean) * inv_std * w_val.z + b_val.z, min_val), max_val);
    out_val.w = fminf(fmaxf((v3 - mean) * inv_std * w_val.w + b_val.w, min_val), max_val);

    *reinterpret_cast<float4*>(output + base + elem) = out_val;
}

// ---------------------------------------------------------------------------
// Generic scalar fallback kernel (unchanged from champion).
// ---------------------------------------------------------------------------
__global__ void fused_groupnorm_hardtanh_scalar_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    int num_groups,
    int group_size,
    float eps,
    float min_val,
    float max_val
) {
    int batch_idx = blockIdx.x / num_groups;
    int group_idx = blockIdx.x % num_groups;
    int base      = batch_idx * num_groups * group_size + group_idx * group_size;

    float local_sum = 0.0f, local_sq = 0.0f;
    for (int i = threadIdx.x; i < group_size; i += blockDim.x) {
        float v = input[base + i];
        local_sum += v;
        local_sq  += v * v;
    }

    unsigned mask = 0xffffffff;
    for (int offset = 16; offset > 0; offset >>= 1) {
        local_sum += __shfl_down_sync(mask, local_sum, offset);
        local_sq  += __shfl_down_sync(mask, local_sq,  offset);
    }

    extern __shared__ float smem[];
    int warp_id   = threadIdx.x >> 5;
    int lane_id   = threadIdx.x & 31;
    int num_warps = (blockDim.x + 31) >> 5;
    float* smem_sum = smem;
    float* smem_sq  = smem + num_warps;

    if (lane_id == 0) {
        smem_sum[warp_id] = local_sum;
        smem_sq [warp_id] = local_sq;
    }
    __syncthreads();

    float block_sum = 0.0f, block_sq = 0.0f;
    if (threadIdx.x < num_warps) {
        block_sum = smem_sum[threadIdx.x];
        block_sq  = smem_sq [threadIdx.x];
    }
    if (warp_id == 0) {
        for (int offset = 16; offset > 0; offset >>= 1) {
            block_sum += __shfl_down_sync(mask, block_sum, offset);
            block_sq  += __shfl_down_sync(mask, block_sq,  offset);
        }
    }

    __shared__ float s_mean, s_inv_std;
    if (threadIdx.x == 0) {
        float mean   = block_sum / group_size;
        float var    = block_sq  / group_size - mean * mean;
        s_mean       = mean;
        s_inv_std    = rsqrtf(var + eps);
    }
    __syncthreads();

    float mean    = s_mean;
    float inv_std = s_inv_std;
    int channel_base = group_idx * group_size;
    for (int i = threadIdx.x; i < group_size; i += blockDim.x) {
        float v   = input[base + i];
        float out = (v - mean) * inv_std * weight[channel_base + i] + bias[channel_base + i];
        out = fminf(fmaxf(out, min_val), max_val);
        output[base + i] = out;
    }
}

// ---------------------------------------------------------------------------
// Host wrapper (same Python-facing API as champion).
// ---------------------------------------------------------------------------
torch::Tensor fused_groupnorm_hardtanh(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int num_groups,
    double eps,
    double min_val,
    double max_val
) {
    TORCH_CHECK(input.is_cuda(),       "input must be a CUDA tensor");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");

    int batch_size   = input.size(0);
    int out_features = input.size(1);
    int group_size   = out_features / num_groups;
    int grid_size    = batch_size * num_groups;

    auto output = torch::empty_like(input);

    const float feps     = static_cast<float>(eps);
    const float fmin_val = static_cast<float>(min_val);
    const float fmax_val = static_cast<float>(max_val);

    // Check alignment for fast path (pointers are multiples of 16 bytes
    // for PyTorch-allocated contiguous tensors; group_size==512 gives the
    // necessary per-block alignment at every (batch,group) boundary).
    bool use_vec4 = (group_size == 512) &&
                    ((reinterpret_cast<uintptr_t>(input.data_ptr<float>())  & 15) == 0) &&
                    ((reinterpret_cast<uintptr_t>(output.data_ptr<float>()) & 15) == 0) &&
                    ((reinterpret_cast<uintptr_t>(weight.data_ptr<float>()) & 15) == 0) &&
                    ((reinterpret_cast<uintptr_t>(bias.data_ptr<float>())   & 15) == 0);

    if (use_vec4) {
        // 128 threads x 4 elems = 512 = group_size; smem = 8 floats
        const int block_size  = 128;
        const size_t smem_bytes = 8 * sizeof(float);
        fused_groupnorm_hardtanh_vec4_kernel<<<grid_size, block_size, smem_bytes>>>(
            input.data_ptr<float>(),
            output.data_ptr<float>(),
            weight.data_ptr<float>(),
            bias.data_ptr<float>(),
            num_groups,
            1.0f / static_cast<float>(group_size),
            feps,
            fmin_val,
            fmax_val
        );
    } else {
        int block_size = group_size;
        if (block_size > 1024) block_size = 1024;
        block_size = ((block_size + 31) / 32) * 32;
        if (block_size > 1024) block_size = 1024;
        int num_warps   = (block_size + 31) / 32;
        size_t smem_bytes = 2 * num_warps * sizeof(float);

        fused_groupnorm_hardtanh_scalar_kernel<<<grid_size, block_size, smem_bytes>>>(
            input.data_ptr<float>(),
            output.data_ptr<float>(),
            weight.data_ptr<float>(),
            bias.data_ptr<float>(),
            num_groups,
            group_size,
            feps,
            fmin_val,
            fmax_val
        );
    }

    return output;
}
