// handles 4 contiguous elements via float4 loads/stores.
// Register-pressure reduction: v0..v3 are NOT kept alive across the reduction.
// Instead we reload from global memory after mean/inv_std are known.
// ---------------------------------------------------------------------------
__global__ __launch_bounds__(128, 4)
void fused_groupnorm_hardtanh_vec4_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    int num_groups,
    float inv_group_size,
    float eps,
    float min_val,
    float max_val
) {
    const int group_size = 512;
    int batch_idx = blockIdx.x / num_groups;
    int group_idx = blockIdx.x % num_groups;

    int base      = batch_idx * num_groups * group_size + group_idx * group_size;
    int chan_base = group_idx * group_size;
    int elem      = threadIdx.x * 4;  // 0..124 * 4

    // --- Phase 1: load once for stats only, then let registers die ---
    float local_sum, local_sq;
    {
        float4 in_val = *reinterpret_cast<const float4*>(input + base + elem);
        float a = in_val.x, b = in_val.y, c = in_val.z, d = in_val.w;
        local_sum = a + b + c + d;
        local_sq  = a*a + b*b + c*c + d*d;
    }  // in_val, a, b, c, d all go out of scope here

    // Warp-level reduction
    unsigned mask = 0xffffffff;
    for (int offset = 16; offset > 0; offset >>= 1) {
        local_sum += __shfl_down_sync(mask, local_sum, offset);
        local_sq  += __shfl_down_sync(mask, local_sq,  offset);
    }

    // 128 threads => 4 warps; store warp sums
    extern __shared__ float smem[];  // 8 floats: 4 sum + 4 sq
    int warp_id = threadIdx.x >> 5;
    int lane_id = threadIdx.x & 31;

    if (lane_id == 0) {
        smem[warp_id]     = local_sum;
        smem[warp_id + 4] = local_sq;
    }
    __syncthreads();

    // First warp reduces the 4 warp sums
    if (warp_id == 0) {
        float ws = (lane_id < 4) ? smem[lane_id]     : 0.0f;
        float wq = (lane_id < 4) ? smem[lane_id + 4] : 0.0f;
        for (int offset = 2; offset > 0; offset >>= 1) {
            ws += __shfl_down_sync(mask, ws, offset);
            wq += __shfl_down_sync(mask, wq, offset);
        }
        if (lane_id == 0) {
            float mean  = ws * inv_group_size;
            float var   = wq * inv_group_size - mean * mean;
            smem[0] = mean;
            smem[1] = rsqrtf(var + eps);
        }
