    float inv_std = smem[1];

    // --- Phase 2: reload input, load weight/bias, normalize, clamp, store ---
    float4 in2  = *reinterpret_cast<const float4*>(input  + base      + elem);
    float4 w4   = *reinterpret_cast<const float4*>(weight + chan_base + elem);
    float4 b4   = *reinterpret_cast<const float4*>(bias   + chan_base + elem);

    float4 out4;
    out4.x = fminf(fmaxf((in2.x - mean) * inv_std * w4.x + b4.x, min_val), max_val);
    out4.y = fminf(fmaxf((in2.y - mean) * inv_std * w4.y + b4.y, min_val), max_val);
    out4.z = fminf(fmaxf((in2.z - mean) * inv_std * w4.z + b4.z, min_val), max_val);
    out4.w = fminf(fmaxf((in2.w - mean) * inv_std * w4.w + b4.w, min_val), max_val);

    *reinterpret_cast<float4*>(output + base + elem) = out4;
