// ---------------------------------------------------------------------------
// Generic scalar fallback kernel.
// ---------------------------------------------------------------------------
__global__ void fused_groupnorm_hardtanh_scalar_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    int num_groups,
    int group_size,
    float eps,
    float min_val,
    float max_val
