#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Fused GEMM+GroupNorm+HardTanh for fixed shape [M, 8192] x [8192, 8192], num_groups=16, group_size=512
// Each CTA handles one batch row and one group (512 output channels)
// Uses 128x128 tiling: 128 output rows (M-dim), 128 output cols (one group covers 512 cols => 4 CTAs per group)
// Threads: 256 threads/CTA arranged as 16x16 for a register tile of 8x8 per thread

template<int TILE_M, int TILE_K, int TILE_N, int THREADS>
__global__ __launch_bounds__(THREADS)
void fused_gemm_gn_ht_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    const float* __restrict__ gemm_bias,
    const float* __restrict__ gn_weight,
    const float* __restrict__ gn_bias,
    float* __restrict__ C,
    int M, int K, int N,
    int num_groups, int group_size,
    float eps, float min_val, float max_val
) {
    const int group_idx = blockIdx.y;
    const int tile_m = blockIdx.x;
    const int group_base_n = group_idx * group_size;
    const int tile_n_in_group = blockIdx.z;
    const int tile_n_global = group_base_n + tile_n_in_group * TILE_N;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane_id = tid % 32;
    const int warp_row = warp_id / 4;
    const int warp_col = warp_id % 4;
    const int thread_row_in_warp = lane_id / 8;
    const int thread_col_in_warp = lane_id % 8;
    const int thread_row = warp_row * 4 + thread_row_in_warp;
    const int thread_col = warp_col * 8 + thread_col_in_warp;

    __shared__ float As[TILE_M][TILE_K];
    __shared__ float Bs[TILE_K][TILE_N];
    __shared__ float group_stats[2];

    float acc[8][8];
    #pragma unroll
    for (int i = 0; i < 8; i++)
        #pragma unroll
        for (int j = 0; j < 8; j++)
            acc[i][j] = 0.0f;

    int num_tiles_k = (K + TILE_K - 1) / TILE_K;
    for (int tile_k = 0; tile_k < num_tiles_k; tile_k++) {
        int k_base = tile_k * TILE_K;
        #pragma unroll
        for (int i = 0; i < TILE_M / 16; i++) {
            int row = i * 16 + tid / 8;
            int col = tid % 8;
            if (tile_m * TILE_M + row < M && k_base + col < K)
                As[row][col] = A[(tile_m * TILE_M + row) * K + k_base + col];
            else
                As[row][col] = 0.0f;
        }
        #pragma unroll
        for (int i = 0; i < TILE_K / 16; i++) {
            int row = i * 16 + tid / 8;
            int col = tid % 8;
            if (k_base + row < K && tile_n_global + col < N)
                Bs[row][col] = B[(k_base + row) * N + tile_n_global + col];
            else
                Bs[row][col] = 0.0f;
