        __syncthreads();

        #pragma unroll
        for (int k = 0; k < TILE_K; k++) {
            #pragma unroll
            for (int i = 0; i < 8; i++) {
                float a_val = As[thread_row * 8 + i][k];
                #pragma unroll
                for (int j = 0; j < 8; j++) {
                    float b_val = Bs[k][thread_col * 8 + j];
                    acc[i][j] += a_val * b_val;
