    #pragma unroll
    for (int i = 0; i < 8; i++) {
        #pragma unroll
        for (int j = 0; j < 8; j++) {
            int out_col = tile_n_global + thread_col * 8 + j;
            if (out_col >= group_base_n && out_col < group_base_n + group_size) {
                local_sum += acc[i][j];
                local_sq += acc[i][j] * acc[i][j];
            }
        }
    }

    unsigned mask = 0xffffffff;
    for (int offset = 16; offset > 0; offset >>= 1) {
        local_sum += __shfl_down_sync(mask, local_sum, offset);
        local_sq += __shfl_down_sync(mask, local_sq, offset);
    }

    __shared__ float warp_sums[8], warp_sqs[8];
    if (lane_id == 0) {
