// handles 4 contiguous elements via float4 loads/stores.
// Input is cached in shared memory during Phase 1 to avoid the second global
// memory read in Phase 2 (strategy_02: smem_input_reuse).
// ---------------------------------------------------------------------------
__global__ __launch_bounds__(128, 4)
void fused_groupnorm_hardtanh_vec4_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    int num_groups,
    float inv_group_size,
    float eps,
    float min_val,
    float max_val
) {
    const int group_size = 512;
    int batch_idx = blockIdx.x / num_groups;
    int group_idx = blockIdx.x % num_groups;

    // Hoist row pointers once
    const float* __restrict__ in_row  = input  + batch_idx * num_groups * group_size + group_idx * group_size;
          float* __restrict__ out_row = output + batch_idx * num_groups * group_size + group_idx * group_size;
    const float* __restrict__ w_row   = weight + group_idx * group_size;
    const float* __restrict__ b_row   = bias   + group_idx * group_size;

    int elem = threadIdx.x * 4;  // 0, 4, 8, ... 508

    // smem layout: [0..511] = cached input floats, [512..515] = warp sums, [516..519] = warp sumsq
    // (reused: after reduction, smem[512]=mean, smem[513]=inv_std)
    extern __shared__ float smem[];  // (512 + 8) floats
    float* smem_input  = smem;           // 512 floats: cached group input
    float* smem_reduce = smem + 512;     // 8 floats: reduction partials

    // --- Phase 1: load input into shared memory and accumulate stats ---
    float4 v = *reinterpret_cast<const float4*>(in_row + elem);
    // Cache in shared memory
    smem_input[elem + 0] = v.x;
    smem_input[elem + 1] = v.y;
    smem_input[elem + 2] = v.z;
    smem_input[elem + 3] = v.w;

    float local_sum = v.x + v.y + v.z + v.w;
    float local_sq  = v.x*v.x + v.y*v.y + v.z*v.z + v.w*v.w;
    // v goes out of scope; registers freed

    // Warp-level reduction
    unsigned mask = 0xffffffff;
    for (int offset = 16; offset > 0; offset >>= 1) {
        local_sum += __shfl_down_sync(mask, local_sum, offset);
        local_sq  += __shfl_down_sync(mask, local_sq,  offset);
    }

    // 128 threads => 4 warps; store warp partials
    int warp_id = threadIdx.x >> 5;
    int lane_id = threadIdx.x & 31;

    if (lane_id == 0) {
        smem_reduce[warp_id]     = local_sum;
        smem_reduce[warp_id + 4] = local_sq;
    }
    __syncthreads();

    // First warp reduces 4 warp partials
    if (warp_id == 0) {
        float ws = (lane_id < 4) ? smem_reduce[lane_id]     : 0.0f;
        float wq = (lane_id < 4) ? smem_reduce[lane_id + 4] : 0.0f;
        for (int offset = 2; offset > 0; offset >>= 1) {
            ws += __shfl_down_sync(mask, ws, offset);
            wq += __shfl_down_sync(mask, wq, offset);
