    const float* __restrict__ w_row   = weight + group_idx * group_size;
    const float* __restrict__ b_row   = bias   + group_idx * group_size;

    float local_sum = 0.0f, local_sq = 0.0f;
    for (int i = threadIdx.x; i < group_size; i += blockDim.x) {
        float v = in_row[i];
        local_sum += v;
        local_sq  += v * v;
